import React, { useState, useEffect } from "react";
import { useAuthorize } from "../context/hook/useAuthorization";
import '../styles/record.css'; // Ensure styles are appropriate
import NavMenu from "./SharedComponents/navMenu";
import { Table } from 'antd';

const ManageRecords = () => {
    const { userAccount } = useAuthorize();
    const [workspaces, setWorkspaces] = useState([]);
    const [loading, setLoading] = useState(false);
    const [selectedName, setSelectedName] = useState('all');

    const fetchWorkspaces = async (nameFilter) => {
        setLoading(true);
        try {
            const query = nameFilter && nameFilter !== 'all' ? `?name=${nameFilter}` : '';
            const response = await fetch(`/api/workspaces/available${query}`, {
                headers: {
                    'Authorization': `Bearer ${userAccount.userToken}`
                }
            });
            const data = await response.json();
            console.log("Fetching with filter:", nameFilter, "Received:", data);
            if (response.ok) {
                setWorkspaces(data);
            } else {
                throw new Error(data.error || "Failed to fetch workspaces");
            }
        } catch (error) {
            console.error("Fetching error:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (userAccount) {
            fetchWorkspaces(selectedName);
        }
    }, [userAccount, selectedName]);

    const handleFilterChange = (e) => {
        setSelectedName(e.target.value);
    };

    const columns = [
        {
            title: 'Name',
            dataIndex: 'name',
            key: 'name',
        },
        {
            title: 'Location',
            dataIndex: 'location',
            key: 'location',
        },
        {
            title: 'Status',
            dataIndex: 'status',
            key: 'status',
        }
    ];

    const workspaceOptions = [
        { label: 'All', value: 'all' },
        { label: 'Workspace A', value: 'Workspace A' },
        { label: 'Workspace B', value: 'Workspace B' }
        // Add more options as needed
    ];

    return (
        <div className="recordpage">
            <NavMenu isAdmin={true} breadcrum="View Workspaces" pagePath="/workspace-management" />
            <div className="workspace-overview">
                <div>
                    <label>Filter by Name:</label>
                    <select onChange={handleFilterChange} value={selectedName}>
                        {workspaceOptions.map(option => (
                            <option key={option.value} value={option.value}>{option.label}</option>
                        ))}
                    </select>
                </div>
                <Table columns={columns} dataSource={workspaces} loading={loading} rowKey="_id" />
            </div>
        </div>
    );
};

export default ManageRecords;
